let state=M.restore(stored(STORE)),view='home',sheet=null,drawer=false,draft='',hidden=profile.hideBalance,theme=stored('nsimbi-concept-theme')||profile.theme,typing=false,checking=null,interrupt=false,failNext=false,refreshing=false,focusReturn=null,addMoneyDismissed=false,attachment=null;
let voiceState={active:false,phase:'idle',detail:''};
const voice=conversation({onChange:next=>{voiceState=next;syncVoice();},onText:text=>{if(voiceState.mode==='dictation'){draft=(draft.trim()?draft.trim()+' ':'')+text;voice.stop();const field=app.querySelector('#message');if(field){field.value=draft;field.focus();}syncVoice();}else send(text);}});
function voiceButton(){const active=voiceState.active&&voiceState.mode!=='dictation',busy=active&&['connecting','listening','thinking','speaking'].includes(voiceState.phase);return `<button id="composer-cta" type="${!active&&draft.trim()?'submit':'button'}" class="send ${!draft.trim()?'conversation-cta':''}" ${active?'data-action="voice-retry"':!draft.trim()?'data-action="voice-start"':''} aria-label="${active?'Listen again':draft.trim()?'Send message':'Start conversation'}" ${typing||busy?'disabled':''}>${Icon(!active&&draft.trim()?'ArrowUp':'Activity')}</button>`;}
function voiceStatus(){return `<div class="conversation-session" data-phase="${voiceState.phase}" ${voiceState.active&&voiceState.mode!=='dictation'?'':'hidden'}><div class="voice-status" role="status"><span class="voice-orb" aria-hidden="true"></span><span><strong>${({connecting:'Connecting',listening:'Listening',thinking:'Thinking',speaking:'Nsimbi is speaking',error:'Microphone unavailable',unavailable:'Voice unavailable',paused:'Voice paused'})[voiceState.phase]||'Conversation mode'}</strong><small>${esc(voiceState.detail)}</small></span></div><div class="voice-session-actions"><span>Voice · Demo assistant</span><button type="button" data-action="voice-end">${Icon('MessageSquare')}Back to typing</button></div><p class="voice-disclosure">Speech uses your browser’s voice service. Payments still need your on-screen approval.</p></div>`;}
function syncVoice(){const form=app.querySelector('#message-form');if(!form)return;form.classList.toggle('voice-active',voiceState.active&&voiceState.mode!=='dictation');form.querySelector('.conversation-session')?.remove();form.insertAdjacentHTML('afterbegin',voiceStatus());const field=form.querySelector('#message');field.hidden=voiceState.active&&voiceState.mode!=='dictation';const mic=form.querySelector('.dictation-button');if(mic){const recording=voiceState.active&&voiceState.mode==='dictation';mic.setAttribute('aria-label',recording?'Stop voice typing':'Voice typing');mic.setAttribute('aria-pressed',String(recording));mic.classList.toggle('recording',recording);mic.disabled=false;}form.querySelector('.dictation-feedback')?.remove();if(voiceState.active&&voiceState.mode==='dictation')form.insertAdjacentHTML('afterbegin',`<div class="dictation-feedback" role="status">${esc(voiceState.detail||'Listening for dictation…')}</div>`);form.querySelector('#composer-cta')?.remove();form.insertAdjacentHTML('beforeend',voiceButton());syncComposerState();}
function voiceAnswer(){const t=M.activeTask(state),last=M.current(state).messages.filter(m=>m.role==='assistant'&&m.text).at(-1)?.text||'Your details are updated.';if(!t||!['draft','review'].includes(t.status))return last;if(!t.forWho&&t.kind!=='send'&&t.kind!=='electricity')return 'Is this for you or someone else?';if(t.kind==='send')return last+' Choose your bank and verify the account on the purchase card before review.';if(t.kind==='electricity'&&!t.meter)return 'What is your 11 digit meter number?';if(t.forWho==='other'&&!t.phone)return 'What mobile number should I use?';if(!t.provider)return 'Which provider would you like?';if(!t.amount)return 'How much would you like to purchase in Uganda shillings?';if(M.CATALOG[t.kind]&&!t.bundle)return t.kind==='data'?'The demo offers 30 MB for 250 shillings. Would you like 30 MB?':'The demo offers 30 minutes for 300 shillings. Would you like 30 minutes?';return 'Your purchase details are filled in. Check the card and tap Review purchase when you are ready. You will approve payment on screen.';}
const namePalette=['#141b5e','#5b21b6','#155e75','#701a75'];let nameColor=0;
let unlocked=false,signInUI=null;try{unlocked=sessionStorage.getItem('nsimbi-demo-unlocked')==='yes';}catch{}
function lockApp(){voice.stop();unlocked=false;signInUI?.dispose();signInUI=null;sheet=null;drawer=false;view='home';try{sessionStorage.removeItem('nsimbi-demo-unlocked');}catch{}render();}
