// In an installed app the phone back control should leave the prototype. It
// never steps back through in-app screens such as Profile, Wallet or a sheet.
(function wireBackExit(){
  const standalone=matchMedia('(display-mode: standalone)').matches||navigator.standalone===true;
  if(!standalone)return;
  try{history.pushState({nsimbiExitGuard:true},'',location.href);}catch{return;}
  addEventListener('popstate',()=>{
    if(history.state?.nsimbiExitGuard)return;
    try{window.close();}catch{}
    setTimeout(()=>{if(!document.hidden)location.replace('about:blank');},40);
  });
})();
render();

// A completed message celebrates only on its first unobscured appearance.
function watchSuccessMessages(){
 successObserver?.disconnect();if(view!=='chat'||successObservedChat!==state.current){successVisible.clear();successObservedChat=view==='chat'?state.current:null;}
 const thread=app.querySelector('.thread');
 if(view!=='chat'||sheet||drawer||document.hidden||!thread)return;
 successObserver=new IntersectionObserver(entries=>{
  if(sheet||drawer||app.inert||document.hidden)return;
  for(const entry of entries){
   const key=entry.target.dataset.celebrationId;if(!entry.isIntersecting||entry.intersectionRatio<.5){successVisible.delete(key);continue;}if(successVisible.has(key))continue;successVisible.add(key);
   const el=entry.target,id=el.dataset.celebrationId,t=M.findTask(state,id);
   if(t?.status!=='paid'||!t.successDismissed)continue;if(Date.now()-(successPlayed.get(id)||0)<2400)continue;successPlayed.set(id,Date.now());
   state=M.markSuccessSeen(state,id);save();
   if(matchMedia('(prefers-reduced-motion: reduce)').matches)continue;
   el.classList.add('just-acknowledged');el.insertAdjacentHTML('afterbegin',confetti());
   later(()=>{el.classList.remove('just-acknowledged');el.querySelector('.confetti')?.remove();},2400);
  }
 },{root:thread,threshold:[.5]});
 for(const el of thread.querySelectorAll('[data-celebration-id]')){const t=M.findTask(state,el.dataset.celebrationId);if(t?.successDismissed)successObserver.observe(el);}
}
document.addEventListener('visibilitychange',()=>{if(!document.hidden)watchSuccessMessages();});

function rewardHint(){const r=R.rewardStatus(state);return r.claimed?'':r.unlocked?'Your reward is ready. Tap your name to receive it.':r.taps>0?'Keep tapping · '+Math.floor(r.taps/R.REWARD_TAPS*100)+'%':'';}
function updateRewardHint(){const r=R.rewardStatus(state);app.querySelector('.reward-name-wrap')?.classList.toggle('is-tapping',r.taps>0&&!r.unlocked);if(r.claimed||r.unlocked)app.querySelector('.reward-discovery')?.remove();const hint=app.querySelector('#reward-hint');if(hint)hint.textContent=rewardHint();app.querySelector('.reward-name-wrap')?.style.setProperty('--reward-progress',r.claimed?0:r.taps/R.REWARD_TAPS);}
function rewardTone(celebrate=false){if(!rewardSound)return;try{const Audio=window.AudioContext||window.webkitAudioContext;if(!Audio)return;rewardAudio??=new Audio();rewardAudio.resume().catch(()=>{});const tones=celebrate?[523.25,659.25,783.99]:[360+R.rewardStatus(state).taps*65];tones.forEach((frequency,i)=>{const oscillator=rewardAudio.createOscillator(),gain=rewardAudio.createGain(),at=rewardAudio.currentTime+i*.085;oscillator.type='sine';oscillator.frequency.value=frequency;gain.gain.setValueAtTime(0,at);gain.gain.linearRampToValueAtTime(.035,at+.008);gain.gain.exponentialRampToValueAtTime(.001,at+(celebrate ? .28 : .065));oscillator.connect(gain);gain.connect(rewardAudio.destination);oscillator.start(at);oscillator.stop(at+(celebrate ? .3 : .075));});}catch{}}
function rewardBalancePulse(){const balance=app.querySelector('.home-hero .mini-balance');if(!balance)return;balance.classList.remove('reward-highlight');void balance.offsetWidth;balance.classList.add('reward-highlight');if(!matchMedia('(prefers-reduced-motion: reduce)').matches)balance.animate([{transform:'scale(1)'},{transform:'scale(1.065)',offset:.4},{transform:'scale(1)'}],{duration:420,easing:'cubic-bezier(.22,1,.36,1)'});later(()=>balance.classList.remove('reward-highlight'),600);}
async function flyRewardGlow(){if(matchMedia('(prefers-reduced-motion: reduce)').matches)return;const source=app.querySelector('.dashboard-name')?.getBoundingClientRect(),dest=app.querySelector('.home-hero .mini-balance')?.getBoundingClientRect();if(!source||!dest)return;const orb=document.createElement('span');orb.className='reward-traveller';orb.setAttribute('aria-hidden','true');document.body.append(orb);const animation=orb.animate([{transform:`translate(${source.x+source.width/2-20}px,${source.y+source.height/2-20}px) scale(.65)`,opacity:1},{transform:`translate(${dest.x+dest.width/2-20}px,${dest.y+dest.height/2-20}px) scale(1.2)`,opacity:.1}],{duration:950,easing:'cubic-bezier(.22,1,.36,1)',fill:'both'});try{await animation.finished;}finally{orb.remove();}}
async function tapDailyReward(){if(rewardUnlocking||rewardClaiming)return;const before=R.rewardStatus(state);if(before.claimed){open('reward-next');return;}if(before.unlocked){openReward();return;}state=R.tapReward(state);save();updateRewardHint();rewardTone();clearTimeout(rewardTapTimer);rewardTapTimer=setTimeout(updateRewardHint,R.REWARD_PAUSE+1);if(!R.rewardStatus(state).unlocked)return;clearTimeout(rewardTapTimer);rewardUnlocking=true;await flyRewardGlow();rewardBalancePulse();rewardTone(true);later(()=>{rewardUnlocking=false;if(view==='home')openReward();},matchMedia('(prefers-reduced-motion: reduce)').matches?0:850);}
function openReward(){const r=R.rewardStatus(state);if(r.claimed||!r.unlocked)return;open('reward');sheet.day=r.day;renderOverlay();}
function rewardCreditLabel(){if(hidden||matchMedia('(prefers-reduced-motion: reduce)').matches)return;const dest=app.querySelector('.home-hero .mini-balance')?.getBoundingClientRect();if(!dest)return;const label=document.createElement('span');label.className='reward-credit-label';label.textContent='+UGX 100';label.setAttribute('aria-hidden','true');document.body.append(label);label.animate([{transform:`translate(${dest.x+dest.width/2-46}px,${dest.bottom+45}px)`,opacity:0},{opacity:1,offset:.15},{transform:`translate(${dest.x+dest.width/2-46}px,${dest.y}px)`,opacity:0}],{duration:800,easing:'cubic-bezier(.2,.7,.2,1)',fill:'both'}).finished.finally(()=>label.remove());}
function receiveDailyReward(button){if(rewardClaiming||sheet?.kind!=='reward')return;const day=sheet.day;rewardClaiming=true;overlay.querySelectorAll('button').forEach(el=>el.disabled=true);button.setAttribute('aria-busy','true');close(()=>{const credit=()=>{const latest=M.restore(stored(STORE)),next=R.claimReward(latest,day);if(next===latest){rewardClaiming=false;state=latest;render({scroll:false});announce(R.rewardStatus(state).claimed?'Next reward available tomorrow.':'A new day has started. Tap your name to unlock today’s reward.');return;}try{localStorage.setItem(STORE,JSON.stringify(next));}catch{rewardClaiming=false;announce('Your reward could not be saved. Please try again.');return;}displayedBalance=latest.balance;state=next;balanceDurationNext=800;render({scroll:false});rewardCreditLabel();later(()=>{rewardClaiming=false;rewardBalancePulse();const notice=app.querySelector('#reward-notice');if(notice)notice.innerHTML='';announce('UGX 100 added to your wallet.');later(()=>{if(view==='home'&&!sheet)open('reward-next');},600);},matchMedia('(prefers-reduced-motion: reduce)').matches?0:800);};if(navigator.locks?.request)navigator.locks.request('nsimbi-daily-reward',credit).catch(()=>{rewardClaiming=false;announce('Your reward could not be received. Please try again.');});else credit();});}

function promotePurchase(id){const currentChat=state.current,positions=new Map([...app.querySelectorAll('.active-purchase-stack [data-card],.active-purchase-stack [data-queue-task]')].map(el=>[el.dataset.card||el.dataset.queueTask,el.getBoundingClientRect().top]));const owner=state.chats.find(c=>c.tasks.some(t=>t.id===id));if(!owner)return;state=M.selectChat(state,owner.id);if(M.findTask(state,id)?.dismissed){state=JSON.parse(JSON.stringify(state));M.findTask(state,id).dismissed=false;}activePurchaseId=id;view='chat';save();render({scroll:false});const target=app.querySelector('[data-card="'+id+'"]')||app.querySelector('[data-queue-task="'+id+'"]');const thread=target?.closest('.thread');if(target)target.style.animation='none';const destination=target&&thread?target.getBoundingClientRect().top-thread.getBoundingClientRect().top+thread.scrollTop-16:null;if(owner.id===currentChat&&!matchMedia('(prefers-reduced-motion: reduce)').matches){for(const el of app.querySelectorAll('.active-purchase-stack [data-card],.active-purchase-stack [data-queue-task]')){el.style.animation='none';const before=positions.get(el.dataset.card||el.dataset.queueTask),after=el.getBoundingClientRect().top;if(before!==undefined&&Math.abs(before-after)>1)el.animate([{transform:`translateY(${before-after}px)`,opacity:.65},{transform:'translateY(0)',opacity:1}],{duration:260,easing:'cubic-bezier(.2,.7,.2,1)'});}}if(target&&thread)easeScroll(thread,destination);}

function notificationButton(){const unread=rewardReminders.notifications.filter(n=>!n.read).length;return IB(unread?'Notifications, '+unread+' unread':'Notifications','updates','Bell').replace('class="icon-button"','class="icon-button notification-button"').replace('</button>',(unread?'<span class="notification-count" aria-hidden="true">'+unread+'</span>':'')+'</button>');}
function syncNotificationButton(){for(const button of app.querySelectorAll('[data-action="updates"]')){const template=document.createElement('template');template.innerHTML=notificationButton();button.replaceWith(template.content.firstElementChild);}}
function persistRewardReminders(next){try{localStorage.setItem(R.REMINDER_STORE,JSON.stringify(next));return true;}catch{return false;}}
function setRewardReminder(button){if(sheet?.kind!=='reward-next'||R.rewardReturnInfo(state,rewardReminders).ready)return;button.disabled=true;button.setAttribute('aria-busy','true');const next=R.scheduleReminder(R.restoreReminders(stored(R.REMINDER_STORE)));if(persistRewardReminders(next)){rewardReminders=next;sheet.reminderError='';renderOverlay({animate:false});overlay.querySelector('.sheet-footer [data-action="close"]')?.focus({preventScroll:true});announce('Reminder set. You’ll get an in-app notification when your next reward is ready.');}else{sheet.reminderError='storage';renderOverlay({animate:false});overlay.querySelector('[data-action="reward-remind"]')?.focus({preventScroll:true});}}
function tickRewardReturn(){if(document.hidden)return;const next=R.deliverReminders(rewardReminders,state);if(next!==rewardReminders&&persistRewardReminders(next)){const hasNew=next.notifications.length>rewardReminders.notifications.length;rewardReminders=next;syncNotificationButton();if(hasNew)announce('Your daily reward is ready. Open Notifications to see it.');}if(sheet?.kind!=='reward-next')return;const info=R.rewardReturnInfo(state,rewardReminders);if(info.ready){if(overlay.querySelector('[role="timer"]')){renderOverlay({animate:false});announce('Your next reward is ready.');}return;}const values={Hours:info.hours,Minutes:info.minutes,Seconds:info.secondsPart};for(const el of overlay.querySelectorAll('[data-reward-time]')){const value=values[el.dataset.rewardTime];if(el.textContent!==value){el.textContent=value;if(!matchMedia('(prefers-reduced-motion: reduce)').matches)el.animate([{opacity:.45},{opacity:1}],{duration:160,easing:'ease-out'});}}overlay.querySelector('[role="timer"]')?.setAttribute('aria-label',info.hours+' hours '+info.minutes+' minutes '+info.secondsPart+' seconds');}
setInterval(tickRewardReturn,1000);
document.addEventListener('visibilitychange',()=>{if(!document.hidden)tickRewardReturn();});
tickRewardReturn();

function highlightFilled(key,taskId=''){const input=taskId?app.querySelector(`[data-task="${taskId}"][data-field="${key}"]`):app.querySelector(`[data-wpage="${key}"]`);if(!input)return;const scroller=input.closest('.service-body,.thread'),box=input.closest('.form-field');if(scroller)easeScroll(scroller,input.getBoundingClientRect().top-scroller.getBoundingClientRect().top+scroller.scrollTop-40);box?.classList.add('filled-highlight');later(()=>box?.classList.remove('filled-highlight'),2000);}

function pendingShortcuts(message){const tasks=(message.taskIds||[]).map(id=>M.findTask(state,id)).filter(t=>t&&WAITING.includes(t.status));return '<div class="bubble pending-shortcuts"><p>'+esc(tasks.length?message.text:'These items are no longer pending.')+'</p>'+(tasks.length?'<div>'+tasks.map(t=>Button(label(t)+(t.amount?' · '+amount(t):''),'queue:'+t.id,'quiet')).join('')+'</div>':'')+'</div>';}
